import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
function check(input, expected) {
  const before = input.slice();
  assert.deepEqual(uniqueTags(input), expected);
  assert.deepEqual(input, before, 'must not change the input');
}
if (mode === 'case') {
  check(['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']);
  check(['js', 'JS', 'jS', 'Js'], ['js']);
  check(['B', 'a', 'b', 'A', 'C', 'c'], ['B', 'a', 'C']);
  check(['', '', 'Tag', 'tag', ' tag', 'TAG ', ' tag', 'tag-name', 'TAG-NAME', 'tag_name'], ['', 'Tag', ' tag', 'TAG ', 'tag-name', 'tag_name']);
  check(['CAFÉ', 'café', 'École', 'école', 'Über', 'über'], ['CAFÉ', 'École', 'Über']);
  // Generated interleaving exercises first spelling and first position independently.
  const input = [];
  for (let i = 0; i < 100000; i++) {
    const k = (i * 7919) % 20011;
    const tag = `tag-${k}`;
    input.push(i % 3 === 0 ? tag.toUpperCase() : tag);
  }
  const seen = new Set();
  const expected = [];
  for (const tag of input) {
    const key = tag.toLowerCase();
    if (!seen.has(key)) { seen.add(key); expected.push(tag); }
  }
  check(input, expected);
  check(['nODE', 'Node', 'NODE'], ['nODE']);
} else if (mode === 'regression') {
  check([], []);
  check(['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']);
  check(['z', 'a', 'z', 'b', 'a'], ['z', 'a', 'b']);
  check(['one'], ['one']);
  check(['', ' ', '', ' x', 'x ', 'x', ' '], ['', ' ', ' x', 'x ', 'x']);
  const input = ['a', 'b'];
  const result = uniqueTags(input);
  assert.notStrictEqual(result, input);
  result.push('c');
  assert.deepEqual(input, ['a', 'b']);
} else if (mode === 'speed' || mode === 'benchmark') {
  // Setup and validation are outside the measured region. All tags are already
  // lowercase so this performance guard also passes on the original function.
  uniqueTags(Array.from({ length: 2000 }, (_, i) => `warm-${i}`));
  let totalMs = 0;
  for (const n of [100000, 200000]) {
    const expected = Array.from({ length: n }, (_, i) => `tag-${i}`);
    const input = expected.concat(expected.slice().reverse());
    const start = performance.now();
    const result = uniqueTags(input);
    const ms = performance.now() - start;
    assert.deepEqual(result, expected);
    if (mode === 'speed') assert.ok(ms < 750, `${input.length} tags took ${ms.toFixed(1)}ms; expected well under one second`);
    totalMs += ms;
  }
  if (mode === 'benchmark') console.log(totalMs.toFixed(6));
} else {
  throw new Error(`unknown mode: ${mode}`);
}
